 impl<P: Probe> DataPlaneSession<P> {
     /// Create a session carrying an arbitrary [`Probe`]. The generic
     /// primitive behind [`from_stream`](DataPlaneSession::from_stream);
     /// the adaptive controller calls this with a `LiveProbe` to enable
     /// per-stream telemetry.
     pub async fn from_stream_with_probe(
         stream: TcpStream,
         trace: bool,
         chunk_bytes: usize,
         payload_prefetch: usize,
         pool: Arc<BufferPool>,
         probe: P,
     ) -> Self {
         let payload_prefetch = payload_prefetch.max(1);
         let chunk_bytes = chunk_bytes.max(crate::buffer::DATA_PLANE_BUFFER_FLOOR);
         Self {
             stream: StallGuardWriter::new(stream, TRANSFER_STALL_TIMEOUT),
             pool,
             trace,
             chunk_bytes,
             payload_prefetch,
             bytes_sent: 0,
             probe,
             phase_trace: None,
             phase_epoch: 0,
             phase_socket: 0,
             phase_write_armed: false,
         }
     }

     pub(crate) fn with_session_phase_trace(
         mut self,
         trace: Option<super::session_phase::BoundSessionPhaseTrace>,
         epoch: u32,
         socket: u32,
     ) -> Self {
         if let Some(trace) = &trace {
             trace.event(
                 "socket_trace_attached",
                 super::session_phase::SessionPhaseFields {
                     epoch: Some(epoch),
                     socket: Some(socket),
                     ..Default::default()
                 },
             );
         }
         self.phase_write_armed = trace.is_some();
         self.phase_trace = trace;
         self.phase_epoch = epoch;
         self.phase_socket = socket;
         self
     }

     fn take_first_payload_write_trace(
         &mut self,
     ) -> Option<super::session_phase::BoundSessionPhaseTrace> {
         if !self.phase_write_armed {
             return None;
         }
         self.phase_write_armed = false;
         let trace = self.phase_trace.clone()?;
         trace.event(
             "socket_write_begin",
             super::session_phase::SessionPhaseFields {
                 epoch: Some(self.phase_epoch),
                 socket: Some(self.phase_socket),
                 ..Default::default()
             },
         );
         Some(trace)
     }

